package controller; import dao.*; import model.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import java.util.*; public class VendorDashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{Integer id=(Integer)r.getSession().getAttribute("vendorId");try{List<Booking>b=new BookingDAO().getBookingsForVendor(id);r.setAttribute("bookings",b);r.getRequestDispatcher("/vendorDashboard.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}}